/* T3 Chat Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="t3-chat-light"] {
  --background: #fcf6fc;
  --foreground: #521856;
  --card: #fcf6fc;
  --card-foreground: #521856;
  --popover: #ffffff;
  --popover-foreground: #521856;
  --primary: #a74370;
  --primary-foreground: #ffffff;
  --secondary: #f2c4e7;
  --secondary-foreground: #753479;
  --muted: #f8e4f4;
  --muted-foreground: #814686;
  --accent: #f2c4e7;
  --accent-foreground: #753479;
  --destructive: #ab4045;
  --destructive-foreground: #ffffff;
  --border: #efbfeb;
  --input: #e8bfdc;
  --ring: #db2476;
  --chart-1: #d920a1;
  --chart-2: #6b07ba;
  --chart-3: #2a4753;
  --chart-4: #e7c365;
  --chart-5: #f4a25d;
  --radius: 0.5rem;
  --sidebar: #f5e5f8;
  --sidebar-foreground: #aa1467;
  --sidebar-primary: #464658;
  --sidebar-primary-foreground: #faf3f7;
  --sidebar-accent: #f8f8f8;
  --sidebar-accent-foreground: #464658;
  --sidebar-border: #ebebeb;
  --sidebar-ring: #db2476;
  --font-sans:
    ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
    Roboto, "Helvetica Neue", Arial, "Noto Sans", sans-serif,
    "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji";
  --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-mono:
    ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono",
    "Courier New", monospace;
  --shadow-color: #000000;
  --shadow-opacity: 0.1;
  --shadow-blur: 3px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0;
  --shadow-offset-y: 1px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-sm:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
  --shadow: 0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
  --shadow-md:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 2px 4px -1px hsl(0 0% 0% / 0.1);
  --shadow-lg:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 4px 6px -1px hsl(0 0% 0% / 0.1);
  --shadow-xl:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 8px 10px -1px hsl(0 0% 0% / 0.1);
  --shadow-2xl: 0 1px 3px 0px hsl(0 0% 0% / 0.25);
  --tracking-normal: 0em;
}

/* Dark mode */
[data-theme="t3-chat-dark"] {
  --background: #221d27;
  --foreground: #d2c4df;
  --card: #2b2631;
  --card-foreground: #dcc6d3;
  --popover: #0e0a0d;
  --popover-foreground: #f7eff4;
  --primary: #a3004c;
  --primary-foreground: #efc2d9;
  --secondary: #352c3c;
  --secondary-foreground: #d5c7e2;
  --muted: #27212b;
  --muted-foreground: #c1b4cf;
  --accent: #453651;
  --accent-foreground: #f7eff4;
  --destructive: #301216;
  --destructive-foreground: #ffffff;
  --border: #3d3138;
  --input: #3e343c;
  --ring: #db2476;
  --chart-1: #a74370;
  --chart-2: #924cc9;
  --chart-3: #e78b2f;
  --chart-4: #af58da;
  --chart-5: #e2356f;
  --radius: 0.5rem;
  --sidebar: #191118;
  --sidebar-foreground: #e0cad6;
  --sidebar-primary: #1d4eda;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #261722;
  --sidebar-accent-foreground: #f5f5f5;
  --sidebar-border: #000000;
  --sidebar-ring: #db2476;
  --font-sans:
    ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
    Roboto, "Helvetica Neue", Arial, "Noto Sans", sans-serif,
    "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji";
  --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-mono:
    ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono",
    "Courier New", monospace;
  --shadow-color: #000000;
  --shadow-opacity: 0.1;
  --shadow-blur: 3px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0;
  --shadow-offset-y: 1px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-sm:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
  --shadow: 0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
  --shadow-md:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 2px 4px -1px hsl(0 0% 0% / 0.1);
  --shadow-lg:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 4px 6px -1px hsl(0 0% 0% / 0.1);
  --shadow-xl:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 8px 10px -1px hsl(0 0% 0% / 0.1);
  --shadow-2xl: 0 1px 3px 0px hsl(0 0% 0% / 0.25);
}
